func lowerBound(_ a: [Int], _ target: Int) -> Int {
  var lo = 0; var hi = a.count
  while lo < hi {
    let mid = lo + (hi - lo) / 2
    if a[mid] >= target { hi = mid }
    else { lo = mid + 1 }
  }
  return lo
}

